class Employee:
    def __init__(self, name, basic):
        self.name = name
        self.__basic = 0
        self.set_basic(basic)

    def get_basic(self):
        return self.__basic

    def set_basic(self, amount):
        if amount >= 0:
            self.__basic = amount
        else:
            print("Salary cannot be negative")

    def monthly_pay(self):
        return self.get_basic()

    def show(self):
        role = self.__class__.__name__
        print(f"{self.name:<12} {role:<10} {self.monthly_pay():>9.2f} Tk")

class Manager(Employee):
    def monthly_pay(self):
        return self.get_basic() * 1.20

class Intern(Employee):
    def monthly_pay(self):
        return self.get_basic() * 0.5

