    Employee("Rahim", 25000),
    Manager("Nasrin", 60000),
    Intern("Tanvir", 16000),
    Manager("Habib", 55000),
]

total = 0
for person in staff:
    person.show()
    total += person.monthly_pay()
print(f"Total monthly payroll: {total:.2f} Tk")

